declare v_quiz uuid; v_q uuid; v_sira int; r jsonb; o jsonb; j int;
begin
  select z.id into v_quiz from public.quizzes z join public.modules m on m.id = z.module_id
   where m.ad = 'Yapay Zeka ve Derin Öğrenme' and z.zorluk = 'orta' limit 1;
  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: Yapay Zeka ve Derin Öğrenme orta'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"Videodaki ev fiyatı örneğinde sinir ağı katsayıları (ağırlıkları) nasıl bulur?","a":"Derin öğrenmenin amacı doğru katsayıları bulmaktır; model bunları deneme ve düzeltme ile arar.","o":[["Başta rastgele katsayılarla tahmin yapar; sonuç gerçek fiyattan uzaksa katsayıları değiştirerek gerçek fiyatlara yaklaşmaya çalışır",true],["Katsayıları kullanıcı elle girer ve model bunları hiç değiştirmez",false],["Katsayılar önce hesaplanır, sonra veri aranır",false],["Her ev için ayrı bir kural yazılır",false]]},{"m":"Videoda anlatılan üç katmandan işlemlerin asıl yapıldığı katman hangisidir?","a":"Giriş katmanı veriyi alır, çıkış katmanı sonucu istenen formatta verir, işlemler gizli katmanda yapılır.","o":[["Gizli (hidden) katman",true],["Giriş (input) katmanı",false],["Çıkış (output) katmanı",false],["Hiçbiri, işlem katmanlar dışında yapılır",false]]},{"m":"Videoda bir Dense katmandaki nöron sayısı için genelde hangi tür değerlerin seçildiği söylenir?","a":"Anlatıcı genellikle 2 üzeri n biçiminde değerlerin kullanıldığını söyler.","o":[["2'nin kuvveti olan değerler (8, 16, 32, 64, 128 gibi)",true],["Her zaman 10'un katları",false],["Yalnızca asal sayılar",false],["Her zaman girdi sayısına eşit bir değer",false]]},{"m":"Veriyi eğitim (train) ve test olarak bölmenin amacı videoda nasıl anlatılır?","a":"Öğretmen örneği: 100 sorunun 90'ı çalışılır, kalan 10 soruyla gerçek öğrenme ölçülür.","o":[["Modelin verilen örnekleri ezberleyip ezberlemediğini, görmediği verilerde gerçekten öğrenip öğrenmediğini ölçmek",true],["Eğitimi iki kat hızlandırmak",false],["Veri miktarını azaltarak hafızadan tasarruf etmek",false],["Test verisinin eğitime katkı yapmasını sağlamak",false]]},{"m":"Videoya göre epoch (epok) nedir?","a":"Model rastgele katsayıyla başlar, hatasına göre düzeltmeyi tekrar tekrar dener; her tekrar bir epoktur.","o":[["Modelin katsayıları iyileştirmek için yaptığı her bir deneme/geçiş",true],["Katmandaki nöron sayısı",false],["Verinin test kısmı",false],["Aktivasyon fonksiyonunun adı",false]]},{"m":"Videodaki ayrıma göre \"öğrencinin dersi geçip geçmeyeceğini tahmin etmek\" hangi problem türüdür?","a":"Sınavdan alınacak puan sürekli bir sayı olduğu için regresyondur; geçti/kaldı ise bir sınıf seçimidir.","o":[["Sınıflandırma (classification)",true],["Regresyon",false],["Kümeleme",false],["Zaman serisi tahmini",false]]},{"m":"Videoda öğrenci skorunu tahmin eden modelde çıkış katmanı neden tek nöronlu ve aktivasyonsuz yapılır?","a":"Regresyonda çıkış katmanı Dense(1)'dir ve genellikle aktivasyon verilmez.","o":[["Tek bir sürekli sayı (skor) tahmin edilen bir regresyon problemi olduğu için",true],["Sınıf sayısı bir olduğu için softmax gerektiği için",false],["Aktivasyon fonksiyonları Keras'ta çıkışta kullanılamadığı için",false],["Model yalnızca 0 veya 1 üretmek zorunda olduğu için",false]]},{"m":"Videoda Keras'a pandas verisini vermeden önce neden astype('float32') yapılır?","a":"Anlatıcı \"float seviyor\" diyerek sayısal verinin float32 numpy dizisi olarak verilmesini önerir.","o":[["Birçok Keras sürümü pandas/integer veriyi doğrudan kabul etmeyip hata verdiği için veriyi float'a çevirmek gerektiğinden",true],["Float32 modeli daha doğru yaptığı için",false],["Veriyi metne çevirmek için",false],["Eğitim veri setini ikiye bölmek için",false]]},{"m":"Videoda optimizer seçimi hakkında ne söylenir?","a":"Anlatıcı optimizer yerine verinin ve model yapısının önemli olduğunu vurgular.","o":[["Adam ve SGD gibi optimizer'ların sonuçları birbirine çok yakındır, seçimin etkisi azdır",true],["Optimizer seçimi modelin başarısını tamamen belirler",false],["Yalnızca SGD regresyonda çalışır",false],["Optimizer yalnızca test aşamasında kullanılır",false]]},{"m":"Videoda ReLU aktivasyon fonksiyonunun davranışı nasıl anlatılır?","a":"ReLU(x) = max(0, x).","o":[["Negatif girişlerde 0, pozitif girişlerde girişin kendisini verir",true],["Girişi her zaman 0 ile 1 arasına sıkıştırır",false],["Pozitif girişlerde 0, negatif girişlerde -1 verir",false],["Girişi iki katına çıkarır",false]]},{"m":"Videoda mantarın zehirli olup olmadığını tahmin eden model için çıkış katmanı ve kayıp fonksiyonu nasıl seçilir?","a":"İki sınıflı (doğru/yanlış) problemde sigmoid ve binary crossentropy kullanılır.","o":[["Tek nöronlu sigmoid çıkış ve binary crossentropy",true],["Tek nöronlu ReLU çıkış ve mse",false],["Sınıf sayısı kadar nöronlu softmax ve mse",false],["Aktivasyonsuz çıkış ve categorical crossentropy",false]]},{"m":"Videodaki örneklere göre \"5 farklı mantar türünden hangisi olduğunu bulmak\" için hangi yaklaşım doğrudur?","a":"Kalori tahmini regresyondur; iki sınıflı sorular sigmoid ister, çok sınıflı sorular farklı çıkış gerektirir.","o":[["Sınıflandırma yapılır ama çok sınıflı olduğu için çıkışta sigmoid değil, sınıf sayısına uygun başka bir yapı gerekir",true],["Regresyon yapılır",false],["Tek nöronlu sigmoid yeterlidir",false],["Hiç aktivasyon kullanılamaz",false]]},{"m":"Videoya göre sigmoid fonksiyonuna çok büyük pozitif ve çok büyük negatif değerler verilirse çıkış nasıl olur?","a":"Sigmoid girişi 0 ile 1 arasına sıkıştırır; grafiği S biçimindedir.","o":[["Büyük pozitifte 1'e, büyük negatifte 0'a yaklaşır",true],["Büyük pozitifte sonsuza, büyük negatifte eksi sonsuza gider",false],["Her iki durumda da 0.5 verir",false],["Büyük pozitifte 0'a, büyük negatifte 1'e yaklaşır",false]]},{"m":"Videoya göre binary crossentropy kaybı yanlış ve kendinden emin bir tahminde nasıl davranır?","a":"Gerçek değer 1 iken 0.01 tahmini çok büyük kayıp üretir.","o":[["Çok büyük bir değer verir; doğru tahminlerde küçük kalır",true],["Her zaman sıfırdır",false],["Tahmin doğruysa büyür",false],["Hiç değişmez",false]]},{"m":"Videoda tahmin sonucu elde edilen sayının hangi anemi tipine karşılık geldiği nasıl bulunur?","a":"Metin etiketler önce sayıya çevrilir; sonuç inverse_transform ile geri çevrilir.","o":[["LabelEncoder'ın inverse_transform işlemiyle sayı tekrar etikete çevrilir",true],["Sonuç zaten metin olarak gelir",false],["Sayı elle tahmin edilir",false],["Softmax'in çıktısı doğrudan tip adını verir",false]]},{"m":"Videoya göre LSTM hangi tür verilerde kullanılır?","a":"Önceki değeri bilmek sonrakini tahmin etmek için önemlidir.","o":[["Sıralı, zaman içinde devam eden veriler (metin, ses, finansal zaman serileri)",true],["Yalnızca tek bir sayıdan oluşan tablolar",false],["Yalnızca resimler",false],["Yalnızca etiketsiz kümeleme verisi",false]]},{"m":"Videoda LSTM hücresindeki üç kapı hangileridir?","a":"Üç kapı geçmişi ne kadar tutacağına, neyin ekleneceğine ve neyin çıkacağına karar verir.","o":[["Unutma (forget), giriş (input) ve çıkış (output) kapısı",true],["Başlangıç, orta ve son kapı",false],["Konvolüsyon, havuzlama ve tam bağlı kapı",false],["Eğitim, doğrulama ve test kapısı",false]]},{"m":"Videoda Tokenizer(num_words=500) ne anlama gelir?","a":"Num_words sözlükteki en popüler kelime sayısını sınırlar.","o":[["En sık geçen 500 kelime dikkate alınır ve metinler bu kelimelerin numaralarından oluşan dizilere çevrilir",true],["Her SMS en fazla 500 karakterle sınırlanır",false],["Eğitim 500 epok sürer",false],["Veri kümesi 500 satıra indirilir",false]]},{"m":"Videoda pad_sequences neden kullanılır?","a":"Vektör işlemleri için tüm dizilerin boyutu aynı olmalıdır.","o":[["Farklı uzunluktaki metin dizilerini eşit boyuta getirip modele verebilmek için",true],["Metni küçük harfe çevirmek için",false],["Etiketleri 0 ve 1'e çevirmek için",false],["Veriyi eğitim ve teste bölmek için",false]]},{"m":"Videoya göre CNN'deki havuzlama (pooling) katmanı için hangisi doğrudur?","a":"Havuzlamada öğrenme yoktur; işleme daha sade ve küçük bir çıktı üretir.","o":[["Öğrenilen katsayı yoktur; boyutu küçültür ve özelliği sadeleştirir",true],["Katsayıları optimizer ile öğrenir",false],["Görüntüyü büyütür",false],["Yalnızca çıkışta bulunur ve softmax uygular",false]]},{"m":"Videodaki max pooling işlemi bir pencerede neyi seçer?","a":"Max pooling, pencerenin en büyük de