  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: Yapay Zeka ve Derin Öğrenme zor'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"Videoya göre model neden tek bir ev için değil, birçok ev verisi üzerinde katsayı arar?","a":"Amaç ezberlemek değil, yeni verilerde de çalışan genel katsayıları bulmaktır.","o":[["Aynı katsayılarla hem bilinen evlerin fiyatını yakalamak hem de hiç görmediği bir evin fiyatını tahmin edebilmek için",true],["Tek ev için katsayı bulmak teknik olarak imkansız olduğu için",false],["Katsayıların sayısını artırmak için",false],["Her evin kendi modelini oluşturmak için",false]]},{"m":"Videoya göre eğitim hatası çok düşük, test hatası belirgin yüksekse ve ikisi arasındaki fark büyükse ne olmuştur?","a":"Aradaki farkın az olması istenir; büyük fark ezberlemeyi gösterir.","o":[["Aşırı öğrenme (overfitting), yani model ezberlemiştir",true],["Model yeterince eğitilmemiştir (underfitting)",false],["Öğrenme oranı sıfırdır",false],["Test verisi eğitime sızmıştır ve sonuç kusursuzdur",false]]},{"m":"Videodaki \"dünyanın en güzel yerini arama\" benzetmesi öğrenme oranı (learning rate) hakkında ne anlatır?","a":"İki uç da sorun yaratabilir; uygun değer deneyerek bulunur.","o":[["Çok küçük adımlar uzaktaki iyi çözümlere ulaşamayabilir, çok büyük adımlar arada kalan iyi çözümleri kaçırabilir",true],["Büyük öğrenme oranı her zaman daha iyidir",false],["Öğrenme oranı sonucu hiç etkilemez",false],["Öğrenme oranı yalnızca test verisinde kullanılır",false]]},{"m":"Videoya göre batch size neyi belirler?","a":"Veri kümesi parçalar halinde (batch) modele verilir.","o":[["Eğitim sırasında modele her adımda kaçar örnek gönderileceğini",true],["Kaç epok çalışılacağını",false],["Gizli katman sayısını",false],["Verinin ne kadarının teste ayrılacağını",false]]},{"m":"Videoda hata değeri belli bir seviyede sabit kalmaya başladıktan sonra epok sayısını artırmak için ne söylenir?","a":"Hata düşmeyi bırakmışsa epok artırmak sonucu değiştirmez.","o":[["Fayda sağlamaz; daha iyi sonuç için başka şeyler (model yapısı, parametreler) denemek daha mantıklıdır",true],["Epok sayısını sürekli artırmak hatayı sıfıra indirir",false],["Modeli baştan yazmak zorunludur",false],["Batch size'ı sıfır yapmak gerekir",false]]},{"m":"Videoda hedef değerler (y) negatif yapılıp çıkış katmanı da ReLU bırakılınca ne olur?","a":"ReLU negatif değer veremez; negatif hedefler öğrenilemez, hedefler pozitif yapılınca model çalışır.","o":[["Çıkış negatif değer üretemediği için hata yüksek kalır, model öğrenemez",true],["Model daha hızlı öğrenir",false],["Hata sıfıra iner",false],["Model hata verip durur",false]]},{"m":"Videoya göre aktivasyon fonksiyonunun doğrusal (lineer) olmaması neden istenir?","a":"Katmanlar arasına doğrusal olmayan aktivasyon konmazsa model doğrusal kalır.","o":[["Gerçek problemler çoğunlukla doğrusal olmadığı için; aktivasyon yoksa ağ doğrusal kalır ve bu problemleri çözemez",true],["Doğrusal fonksiyonlar türevlenemediği için",false],["Doğrusal fonksiyonlar bellek harcadığı için",false],["Doğrusal olmayan fonksiyonlar çıkışı her zaman 1 yaptığı için",false]]},{"m":"Videoda gizli katmanlarda sigmoid yerine ReLU'nun sık kullanıldığı hangi gerekçeyle anlatılır?","a":"Sigmoid daha çok ikili çıkış için; gizli katmanlarda ReLU tercih edilir.","o":[["Sigmoid 0 veya 1'e yakın evet/hayır benzeri çıktı verdiği için gizli katmanda yetersiz kalır; ReLU gizli katmanda sık kullanılan bir yöntemdir",true],["ReLU yalnızca çıkış katmanında çalıştığı için",false],["Sigmoid Keras'ta bulunmadığı için",false],["ReLU negatifleri koruduğu için",false]]},{"m":"Videoda sınıflar yaklaşık yarı yarıya dağılmışken modelin ilk doğruluğunun yaklaşık %63 çıkması nasıl yorumlanır?","a":"Sınıflar dengeliyken %50 rastgele tahmindir; %63 bu referansa göre zayıf bir artıdır.","o":[["Rastgele tahminden (yaklaşık %50) biraz iyi, ancak yetersiz; modeli güçlendirmek gerekir",true],["Mükemmel bir sonuçtur",false],["Model hiç öğrenmemiştir ve %0'dır",false],["Sonuç yalnızca test setinde geçerlidir",false]]},{"m":"Videoda validation ile test arasındaki fark nasıl anlatılır?","a":"Validation eğitim sırasında kalite takibi içindir; test eğitim bitince kullanılır.","o":[["Validation eğitim sırasında yapılan ara kontroldür; test ise eğitim bittikten sonra yapılan asıl ölçümdür",true],["Validation eğitimden sonra, test eğitimden önce yapılır",false],["İkisi aynı şeydir",false],["Validation yalnızca regresyonda kullanılır",false]]},{"m":"Videoda ilk Dense katmanındaki input_dim değeri neyi göstermelidir?","a":"Videoda 8 özellik vardı; input_dim 9 yapılınca hata alınır.","o":[["Veri kümesindeki özellik (sütun) sayısını; yanlış verilirse model hata verir",true],["Örnek sayısını",false],["Gizli katmandaki nöron sayısını",false],["Epok sayısını",false]]},{"m":"Videoda sigmoid formülündeki x neyi temsil eder?","a":"x, w·x toplamıdır; sigmoid bu değeri 0 ile 1 arasına dönüştürür.","o":[["Girdilerin ağırlıklarla çarpılıp toplanmasıyla oluşan değeri",true],["Epok sayısını",false],["Euler sayısını",false],["Verideki satır sayısını",false]]},{"m":"Videodaki 4 mantarlı hesapta gerçek değerler 1, 0, 1, 0 iken tahminler gerçeğin tersine çok yakınsa toplam kayıp nasıl çıkar?","a":"Anlatıcının hesabında yanlış tahminlerin toplamı büyük çıkarken doğru tahminlerde kayıp sıfıra yakındır.","o":[["Çok büyük; ters ve kararlı tahminler en yüksek kaybı üretir",true],["Sıfır",false],["Tahminler 0'a yakın olduğu için küçük",false],["Hesaplanamaz",false]]},{"m":"Videoda 9 farklı anemi tipini sınıflandıran modelde çıkış katmanı nasıl kurulur?","a":"Softmax çıkış sayısı sınıf sayısına eşit olmalıdır; farklı sayı hata verir.","o":[["9 nöronlu Dense katman ve softmax aktivasyonu; kayıp olarak categorical crossentropy",true],["Tek nöronlu Dense katman ve sigmoid",false],["9 nöronlu Dense katman ve ReLU, kayıp mse",false],["Sınıf sayısından bağımsız herhangi bir nöron sayısı",false]]},{"m":"Videoda LabelEncoder ile sayıya çevrilen sınıflar neden ayrıca to_categorical (one-hot) ile 0/1 vektörlerine dönüştürülür?","a":"Tipler birbirine üstün değildir; one-hot gösterim bu yanlış sıralamayı önler.","o":[["Sınıf numaraları arasında büyüklük/üstünlük ilişkisi varmış gibi algılanmasın diye",true],["Veriyi küçültmek için",false],["Eğitimi test verisinden ayırmak için",false],["Softmax'i kapatmak için",false]]},{"m":"Videoya göre train/test ayrımı overfitting'i engeller mi, ne işe yarar?","a":"Ayrım öğrenmeyi artırmaz, ölçümü doğrulaştırır.","o":[["Overfitting'i engellemez; ama başarı ölçümünü görülmemiş verilerle yapıp daha gerçekçi hale getirir",true],["Overfitting'i tamamen ortadan kaldırır",false],["Eğitim doğruluğunu artırır",false],["Yalnızca veri boyutunu küçültür",false]]},{"m":"Videoya göre unutma kapısındaki sigmoid çıkışı 0'a yakınsa geçmişten gelen bilgiye ne olur?","a":"Sigmoid 0 ile 1 arasında olduğundan \"ne kadar unutulacağı\" oranını belirler.","o":[["Büyük ölçüde unutulur; 1'e yakınsa neredeyse hiç unutulmadan korunur",true],["Hiç değişmeden korunur",false],["Bilgi ikiye katlanır",false],["Yalnızca çıkış kapısına gider",false]]},{"m":"Videodaki Merkez Bankası faiz kararı örneği unutma kapısının hangi davranışını göstermek için verilir?","a":"Yeni bir plan gerektiren durumda geçmiş bilgi büyük ölçüde unutulur.","o":[["Beklenmedik büyük bir değişimde geçmiş bilginin önemi kalmaz, kapı 0'a yaklaşır; olağan bir günde ise geçmiş daha az unutulur",true],["Kapının her zaman 1 olduğunu",false],["Çıkış kapısının hiç çalışmadığını",false],["Geçmiş verinin silinmesi gerektiğini",false]]},{"m":"Videoda yeni bir SMS'in spam olup olmadığı tahmin edilirken tokenizer'da neden tekrar fit_on_texts çağrılmaz?","a":"Anlatıcının klasör renk örneği: sistem eğitildiği gibi kullanılmalıdır.","o":[["Tokenizer yeniden eğitilirse kelime numaraları değişir ve modelin öğrendiği eşleşme bozulur; sadece mevcut tokenizer ile texts_to_sequences yapılır",true],["fit_on_texts yalnızca test verisi içindir",false],["Tahminde tokenizer hiç kullanılmaz",false],["Tekrar çağırmak hesap süresini uzatır",false]]},{"m":"Videodaki Embedding katmanında input_length=20 değeri neden 20 seçilmiştir?","a":"Input_dim 500 sözlük boyutu (num_words), output 100 gömme boyutu, input_length 20 pad uzunluğudur.","o":[["Metinler pad_sequences ile 20 uzunluğa eşitlendiği için, katmanın giriş uzunluğu bununla aynı olmalıdır",true],["Embedding çıkışının boyutu olduğu için",false],["Kelime sayısı 20 olduğu için",false],["Epok sayısıyla uyumlu olması için",false]]},{"m":"Videoda anlatıcı metni küçük harfe çevirmeyi neden yapmamıştır?","a":"Anlatıcı bunu veri hakkındaki sezgisine dayandırır; test etmediğini de belirtir.","o":[["Spam mesajlar genelde büyük harfle yazıldığı için bu bilgiyi kaybetmek performansı düşürebilir diye düşünmüştür",true],["Tokenizer büyük harfi zorunlu kıldığı için",false],["Küçük harfe çevirme Keras'ta yasak olduğu için",false],["Veri zaten küçük harfliydi",false]]},{"m":"Videoya göre eğitilmiş bir metin modelini sonra kullanmak için modelin yanında başka neyin saklanması gerekir?","a":"Model, metni aynı kelime-numara eşleşmesiyle görmek zorundadır.","o":[["Eğitimde kullanılan tokenizer; yoksa metinler aynı numaralara çevrilemez",true],["Yalnızca epok sayısı",false],["Test verisinin tamamı",false],["Kaggle hesap bilgileri",false]]},{"m":"Videoda ağ derinleştikçe görüntü tensörünün boyutları nasıl değişir?","a":"Örnekte 224x224 giriş 112x112, 56x56, 28x28 ve 14x14'e inerken filtre sayısı 64'ten 512'ye çıkar.","o":[["Genişlik ve yükseklik küçülür, kanal (filtre) sayısı yani kalınlık artar",true],["Genişlik ve yükseklik artar, kalınlık azalır",false],["Tüm boyutlar sabit kalır",false],["Yalnızca kalınlık azalır",false]]},{"m":"Videoda LSTM'in işlediği düz vektörlerle karşılaştırıldığında CNN'in girdisi olan resim nasıl temsil edilir?","a":"Resim pikselleri sayıya çevrilerek matris, renkli resimlerde tensör oluşturur.","o":[["İki (veya renkliyse daha fazla) boyutlu bir sayı matrisi/tensörü olarak",true],["Tek boyutlu bir vektör olarak",false],["Yalnızca metin olarak",false],["Tek bir sayı olarak",false]]},{"m":"Videoya göre video verisi hangi mantıkla temsil edilir?","a":"Video art arda dizilmiş karelerdir ve tensör olarak işlenir.","o":[["Art arda gelen iki boyutlu resimlerin oluşturduğu, yine tensör biçiminde bir veri olarak",true],["Tek bir sayı olarak",false],["Yalnızca ses vektörü olarak",false],["Resimlerden bağımsız, metin dizisi olarak",false]]},{"m":"Videoya göre resim neden önce sayısal bir diziye (NumPy array) çevrilir?","a":"Pillow ile açılan resim np.array ile matrise çevrilerek modele hazır hale getirilir.","o":[["Yapay zeka modelleri sayılarla çalışır; sayıya çevrilen veri katsayılarla çarpılıp aktivasyon fonksiyonlarına verilebilir",true],["Resim dosyası boyutunu küçültmek için",false],["Renkleri kalıcı olarak silmek için",false],["Python resim açamadığı için",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
    v_sira := v_sira + 1;
    insert into public.questions (quiz_id, metin, sira, aciklama)
      values (v_quiz, r->>'m', v_sira, r->>'a') returning id into v_q;
    j := 0;
    for o in select * from jsonb_array_elements(r->'o') loop
      j := j + 1;
      insert into public.question_options (question_id, metin, dogru, sira)
        values (v_q, o->>0, (o->>1)::boolean, j);
    end loop;
  end loop;
end $q$;

